import 'package:path/path.dart' as p;
import 'package:sqflite/sqflite.dart';
class LocalDatabase{LocalDatabase._();static final instance=LocalDatabase._();Database? _db;Future<Database> get database async=>_db??=await _open();
Future<Database> _open()async{final dir=await getDatabasesPath();return openDatabase(p.join(dir,'astrodaily.db'),version:2,onCreate:(db,v)async{await db.execute('CREATE TABLE profile(id INTEGER PRIMARY KEY,sign TEXT NOT NULL)');await db.insert('profile',{'id':1,'sign':'aries'});await _tables(db);},onUpgrade:(db,o,n)async{if(o<2){await db.execute("ALTER TABLE journal ADD COLUMN tags TEXT NOT NULL DEFAULT '[]'");await db.execute('ALTER TABLE journal ADD COLUMN mood TEXT');await db.execute('ALTER TABLE journal ADD COLUMN updated_at TEXT');await _tables(db);}});}
Future<void> _tables(DatabaseExecutor db)async{await db.execute("CREATE TABLE IF NOT EXISTS saved(id TEXT PRIMARY KEY,sign TEXT,title TEXT,body TEXT,prompt TEXT,content_type TEXT NOT NULL DEFAULT 'reading')");await db.execute("CREATE TABLE IF NOT EXISTS journal(id TEXT PRIMARY KEY,day TEXT NOT NULL,body TEXT NOT NULL,prompt TEXT NOT NULL,tags TEXT NOT NULL DEFAULT '[]',mood TEXT,updated_at TEXT)");await db.execute('CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL)');await db.execute("CREATE TABLE IF NOT EXISTS reading_history(id TEXT PRIMARY KEY,viewed_at TEXT NOT NULL,completion_state TEXT NOT NULL DEFAULT 'opened')");await db.execute('CREATE TABLE IF NOT EXISTS lunar_events(id TEXT PRIMARY KEY,payload TEXT NOT NULL)');await db.execute('CREATE TABLE IF NOT EXISTS content_cache(path TEXT PRIMARY KEY,version TEXT NOT NULL,payload TEXT NOT NULL,updated_at TEXT NOT NULL)');await db.execute("CREATE TABLE IF NOT EXISTS reminders(id TEXT PRIMARY KEY,type TEXT NOT NULL,enabled INTEGER NOT NULL,local_time TEXT NOT NULL,weekdays TEXT NOT NULL DEFAULT '[]',quiet_start TEXT,quiet_end TEXT)");}}
